import{_ as n,c as t,b as a,o as s}from"./app-CpW5lisY.js";const o={};function l(i,e){return s(),t("div",null,e[0]||(e[0]=[a(`<p><a href="https://webkul.com/blog/shopify-multivendor-marketplace-new-theme-launched/" target="_blank" rel="noopener noreferrer">Multi-vendor Marketplace App</a> helps you to convert your store into a multi-functional marketplace. You can register multiple sellers &amp; allow them to publish their products on your store. The app is loaded with tons of features and recently introduced a new one &quot;<strong>Minimum Purchase Amount for Orders</strong>&quot;.</p><p>With this feature, You can allow your sellers to set a Minimum Purchase Amount for Orders. Thus, sellers can restrict the purchase of the customers by setting up a minimum order value.</p><p>Now, once the customer adds a product to the cart, he/she can proceed to checkout only if the checkout condition satisfies i.e. <em>the validated cart amount should be greater than or equal to the minimum purchase amount set by the seller.</em> Else, the customer will not be able to proceed to check out.</p><p>Check the below video of Minimum Purchase Amount:</p><p>Let&#39;s understand it with an example:-</p><p>Price of Product A: $500, Price of Product B: $1000<br><strong>Minimum Purchase Amount for orders: $600</strong></p><p>Customer A adds Product A to Cart worth $500 i.e. Total Order Amount=$500:<br><strong>FAILED TO CHECK OUT</strong> (as the <strong>Total Order Amount</strong> $<strong>500</strong> &lt; <strong>Minimum Purchase Amount $600</strong>)</p><p>Customer B adds Product B to Cart worth $1000 i.e. Total Order Amount=$1000:<br><strong>CHECK OUT</strong> <strong>SUCCESSFULLY</strong> (as <strong>Total Order Amount ($1000)</strong> &gt; <strong>Minimum Purchase Amount ($600))</strong></p><p><strong>One Limitation:-</strong></p><p><strong>Please</strong> <strong>Note</strong>:- Discount codes can be applied on check out page i,e. If the checkout condition satisfies (i.e. the cart amount exceeds the minimum purchase amount), the customer will proceed to checkout. But further, the customer can apply a discount on the order that may result in the final order amount lesser than the minimum purchase amount.</p><p>Thus, the order amount can be less than the minimum purchase amount set by the seller once the discount applied.</p><p>Let&#39;s understand it in detail.</p><h3 id="configuration-admin-end" tabindex="-1"><a class="header-anchor" href="#configuration-admin-end"><span>Configuration-ADMIN END</span></a></h3><p>In order to make this feature work for your sellers, first, you need to enable this tab from your admin panel. Here are some simple steps:-</p><ul><li>Go to the Multi-vendor admin panel.</li><li>Visit the <strong>Configuration</strong> menu.</li><li>Click the <strong>General Configuration</strong> submenu.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/generalconfig.webp" alt="General Configuration-minimum purchase amount"></p><ul><li>In the General Configuration, scroll down to get the &quot;<strong>Minimum Purchase Amount for Orders</strong>&quot; tab.</li><li><strong>Enable</strong> the tab and click the <strong>Save Changes</strong> button.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/miniorderconfig.webp" alt="multi-vendor marketplace-configuration"></p><p>As soon as you enable this tab, the same will start getting reflected at the seller side.</p><p>Introduced a new sub-menu &quot;General Configuration&quot; at the seller side. Now, sellers will get the option &quot;Minimum Purchase Amount for Orders&quot; in the General Configuration menu of the app.</p><p>Let&#39;s understand this in detail.</p><h3 id="general-configuration-seller-end" tabindex="-1"><a class="header-anchor" href="#general-configuration-seller-end"><span>General Configuration: SELLER END</span></a></h3><p>Once the &quot;Minimum Purchase Amount for Orders&quot; tab is enabled by the merchant, the same will reflect in the <strong>General Configuration</strong> menu of the seller panel.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/generalconfigseller.webp" alt="general configuration"></p><p>Clicking the General Configuration menu, the seller will get the following options:</p><p>Firstly, Seller needs to enable the &quot;<strong>Minimum Purchase Amount for Orders</strong>&quot; tab.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/enablegeneralconfigseller.webp" alt="configuration"></p><p>Once the tab gets enabled, the seller will get all the options to set the purchase amount for the customers.</p><p>By default, the Purchase amount will be applicable to all the customers. In this case, the seller needs to set a fixed purchase amount that will be applicable to all the customers.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/generalconfigsellerenable.webp" alt="minimum purchase amount-Seller Panel"></p><h3 id="slot-pricing-case" tabindex="-1"><a class="header-anchor" href="#slot-pricing-case"><span><strong>SLOT PRICING CASE</strong></span></a></h3><p>This functionality is also compatible with Slot Pricing feature app where the seller will be able to choose whether he wants to apply &quot;minimum purchase&quot; for &quot;<strong>All Customers</strong>&quot; or &quot;<strong>Specific Tagged Customers</strong>&quot;.</p><p>In case, You have enabled the <a href="https://webkul.com/blog/shopify-multivendor-marketplace-slot-pricing/" target="_blank" rel="noopener noreferrer">Slot Pricing feature</a> on your end, the sellers will get the option to set a different minimum purchase amount for each customer based on the tags assigned to them.</p><p>In this case, the seller will get the option to set different purchase amounts for each customer tag. The seller needs to select if the <strong>minimum purchase amount for orders will be applicable for</strong> all the customers or only for some specific tag customers</p><p>Now, the purchase amount required for each customer will be different based on the tags assigned to them.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/06/image-29-1200x832.png" alt="minimum purchase amount-Slot Price case"></p><p>That is how sellers can set a minimum purchase amount for orders from their respective seller panels of the multi-vendor app.</p><h3 id="how-to-configure-front-end" tabindex="-1"><a class="header-anchor" href="#how-to-configure-front-end"><span>How to Configure Front End</span></a></h3><p>Now, once the customers purchase products from your store, the checkout condition appears on the cart page after adding the codes into liquid files.</p><p>In order to display the checkout conditions on the Cart page, you need to add the codes to the suggested liquid files (as shown in the screenshot).</p><ul><li>Go to the Multi-vendor Admin Panel.</li><li>Visit Configuration</li><li>Click the Instruction for Marketplace menu.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/instructioncode.webp" alt="Multivendor-minimum purchase amount-Add codes"></p><ul><li>Scroll down to get the codes for “Seller’s Minimum Purchase Amount for Orders”.</li><li>Copy the code from there &amp; add it to the instructed liquid files.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/codemini.webp" alt="Instruction for Marketplace"></p><p><strong>Display checkout conditions on cart page:-</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>wk_minimum_purchase_div<span class="token punctuation">&quot;</span></span> <span class="token special-attr"><span class="token attr-name">style</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token value css language-css"><span class="token property">display</span><span class="token punctuation">:</span>none<span class="token punctuation">;</span></span><span class="token punctuation">&quot;</span></span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>Code to hide checkout button if the condition fails:-</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    style=&quot;display:none;&quot;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>TO DISPLAY TRANSLATED LABELS ON FRONTEND</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">Copy the below-given code &amp; paste it to theme.liquid just above <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>body</span><span class="token punctuation">&gt;</span></span> tag:</span>
<span class="line"></span>
<span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%</span> <span class="token keyword">render</span> <span class="token string">&#39;wk-mvm-variables&#39;</span> <span class="token delimiter punctuation">%}</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>To add the codes to the liquid file, please follow below-given steps:-</p><ul><li>Go to the Shopify store back end.</li><li>Click the <strong>Online Store</strong> menu in the <strong>sales channel</strong> section.</li><li>Click the <strong>Themes</strong> &amp; select the <strong>Edit Code</strong> Option from the drop-down menu.</li><li>Get the template files &amp; add the codes as instructed in the app.</li></ul><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/02/Screenshot-2020-02-05T123409.155-1200x613.png" alt="Theme"></p><p>Once the codes are added let&#39;s see how it appears on the front end.</p><p><strong>Show minimum purchase amount on the seller profile page</strong></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">    <span class="token liquid language-liquid"><span class="token delimiter punctuation">{%</span> <span class="token keyword">assign</span> selected_tag <span class="token operator">=</span> <span class="token object">customer</span><span class="token punctuation">.</span>tags<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token delimiter punctuation">%}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>script</span><span class="token punctuation">&gt;</span></span><span class="token script"><span class="token language-javascript"><span class="token keyword">var</span> wk_selected_tag <span class="token operator">=</span> <span class="token string">&quot;<span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> selected_tag <span class="token delimiter punctuation">}}</span></span>&quot;</span><span class="token punctuation">;</span></span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>script</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="front-end-view" tabindex="-1"><a class="header-anchor" href="#front-end-view"><span>Front End View</span></a></h3><p>If the cart amount is lesser than that minimum purchase amount, the check out condition gets failed &amp; customer will not be able to proceed to check out.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/06/image-32-1126x1024.png" alt="Cart Page"></p><p>If the cart amount is equal or greater than the minimum purchase amount, customer can proceed for checkout.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/06/image-33-1126x1024.png" alt="Cart Validation-checkout condition"></p><p>This is all about the Minimum Purchase Amount feature of the Multi-vendor Marketplace app for Shopify.</p><h3 id="minimum-purchase-amount-on-seller-pages" tabindex="-1"><a class="header-anchor" href="#minimum-purchase-amount-on-seller-pages"><span>Minimum Purchase Amount On Seller Pages</span></a></h3><p>In case, you are using <a href="https://webkul.com/blog/shopify-multivendor-marktplace-custom-seller-profile-page-new-theme/#panel-5" target="_blank" rel="noopener noreferrer">Theme 4</a> of the seller profile page then, you can display the minimum purchase amount on the seller listing as well as on the seller profile page.</p><p><strong>On the Seller Listing Page</strong></p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/12/Seller-Profile-–-Demo-Store-AUD--1200x627.png" alt="Seller-Profile-–-Demo-Store-AUD-"></p><p><strong>On the Seller Profile Page</strong></p><p>Similarly, on the seller profile page, you can view the minimum purchase amount set by this seller.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2019/12/Seller-Profile-–-Demo-Store-AUD-1-1200x627.png" alt="Seller-Profile-–-Demo-Store-AUD-1"></p><p><strong>NOTE</strong>:- Currently, this feature is available in <a href="https://webkul.com/blog/shopify-multivendor-marktplace-custom-seller-profile-page-new-theme/#panel-5" target="_blank" rel="noopener noreferrer">Theme 4</a> only, but in case you want this for other seller profile page themes as well, do send us a request to <strong>support@webkul.com</strong>.</p><h3 id="minimum-purchase-amount-on-product-page" tabindex="-1"><a class="header-anchor" href="#minimum-purchase-amount-on-product-page"><span>Minimum Purchase Amount on Product Page</span></a></h3><p>You can now show the minimum purchase amount on the product description page of your store. All you need to do is just go to the &quot;<strong>Instruction for Marketplace</strong>&quot; menu under the &quot;<strong>Configuration</strong>&quot; menu and add the code to the product.liquid template file.</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2025/09/codemini.webp" alt="order amount on product page"></p><div class="language-liquid line-numbers-mode" data-highlighter="prismjs" data-ext="liquid"><pre><code><span class="line">Copy the below-given code and add it to the **product.liquid** (or **product-template.liquid**):</span>
<span class="line"></span>
<span class="line">    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>wk_product_mpa<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-product_id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> <span class="token object">product</span><span class="token punctuation">.</span>id <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-selected_tag</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token liquid language-liquid"><span class="token delimiter punctuation">{{</span> <span class="token object">customer</span><span class="token punctuation">.</span>tags<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span> <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>After adding the code, that is how the minimum purchase amount will appear on the product page of your store. Have a look:</p><p><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2020/03/Personalized-Coffee-Mug-–-Demo-Store-AUD-1-2-1200x597.png" alt="product page"></p>`,76)]))}const p=n(o,[["render",l]]),u=JSON.parse('{"path":"/zenith/configuration/Minimum%20Purchase%20Amount.html","title":"Minimum Purchase Amount for Orders","lang":"en-US","frontmatter":{"title":"Minimum Purchase Amount for Orders","description":"Minimum Purchase Amount for Orders","date":"2025-07-10T00:00:00.000Z","author":"Chirag Tyagi"},"headers":[{"level":3,"title":"Configuration-ADMIN END","slug":"configuration-admin-end","link":"#configuration-admin-end","children":[]},{"level":3,"title":"General Configuration: SELLER END","slug":"general-configuration-seller-end","link":"#general-configuration-seller-end","children":[]},{"level":3,"title":"SLOT PRICING CASE","slug":"slot-pricing-case","link":"#slot-pricing-case","children":[]},{"level":3,"title":"How to Configure Front End","slug":"how-to-configure-front-end","link":"#how-to-configure-front-end","children":[]},{"level":3,"title":"Front End View","slug":"front-end-view","link":"#front-end-view","children":[]},{"level":3,"title":"Minimum Purchase Amount On Seller Pages","slug":"minimum-purchase-amount-on-seller-pages","link":"#minimum-purchase-amount-on-seller-pages","children":[]},{"level":3,"title":"Minimum Purchase Amount on Product Page","slug":"minimum-purchase-amount-on-product-page","link":"#minimum-purchase-amount-on-product-page","children":[]}],"git":{"updatedTime":1759748118000,"contributors":[{"name":"pratik","username":"pratik","email":"pratik@webkul.com","commits":2,"url":"https://github.com/pratik"}],"changelog":[{"hash":"90ec5b5f52eba83d1e9c295c7ccf89e3db66275b","time":1759748118000,"email":"pratik@webkul.com","author":"pratik","message":"fix conflcit"},{"hash":"bbe1b03e5e919255cadeb8590203b7f1b2e7378e","time":1757583088000,"email":"pratik@webkul.com","author":"pratik","message":"add some new file"}]},"filePathRelative":"zenith/configuration/Minimum Purchase Amount.md"}');export{p as comp,u as data};
